use crate::{bq049 as b,catalog,model::*,rules::*,unit_support::*};
fn setup()->(Game,String){let mut g=game();fund(&mut g,0,"JC042",2);let id=held(&mut g,b::ID,0);(g,id)}
fn play(id:&str,mode:&str,target:Option<&str>)->Action{Action{card_id:Some(id.into()),ability_id:Some(b::KEY.into()),option:Some(mode.into()),region:target.map(|s|s.strip_prefix("region:").unwrap().parse().unwrap()),..Action::new("play")}}
fn top(g:&mut Game){for _ in 0..16{if g.pending.is_some()||g.stack.is_empty(){return;}crate::jc029_tests::pass_top(g);}panic!("stack did not settle");}
fn bad(reference:&Game,g:&Game){assert!(Game::from_persisted(&serde_json::to_string(g).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(reference);r.game=g.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn bq049_original_closed_all_three_fast_modes(){let c=catalog::card(b::ID);assert_eq!((c.cost,c.color.as_str(),c.supported),(2,"红",false));assert_eq!(c.loyalty,["红色"]);assert_eq!(c.subtypes,["命令","强化"]);let d=b::definition();assert_eq!(d.abilities[0].modes.len(),3);assert!(matches!(d.abilities[0].timing,Timing::Fast));for i in 0..3{let mut x=d.clone();x.abilities[0].modes[i].ops.clear();assert!(b::validate_definition(b::ID,&x).is_err());}assert!(b::validate_definition("JC001",&d).is_err());}
#[test]fn bq049_paid_real_generation_and_no_task_bonus(){let(mut g,id)=setup();act(&mut g,0,play(&id,"generate",Some("region:0")));assert_eq!(g.resources(0),0);top(&mut g);let c=g.regions[0].cards.iter().find(|c|c.definition=="TK010").unwrap();assert_eq!(c.owner,0);assert!(c.generated.is_some());assert_eq!(g.regions[0].influence,[0,0]);restore(&mut g);}
#[test]fn bq049_sacrifice_actual_own_character_then_four_honor_and_empty_boundary(){for empty in [false,true]{let(mut g,id)=setup();let victim=if empty{None}else{Some(field(&mut g,"TK010",0))};field(&mut g,"JC125",1);act(&mut g,0,play(&id,"sacrifice",None));top(&mut g);if let Some(v)=victim{assert_eq!(g.players[0].honor,0);let p=g.pending.clone().unwrap();reject(&mut g,1,Action{choice_id:Some(p.choice.id),selected:Some(vec![v.clone()]),..Action::new("choose")});choose(&mut g,vec![v]);assert_eq!(g.players[0].honor,4);assert!(!g.batch3_physical_cards().any(|c|c.definition=="TK010"));}else{assert!(g.pending.is_none());assert_eq!(g.players[0].honor,0);}restore(&mut g);}}
#[test]fn bq049_mobility_grants_existing_own_core_and_tentacles_only(){let(mut g,id)=setup();let token=field(&mut g,"TK010",0);let enemy=field(&mut g,"TK010",1);let ordinary=field(&mut g,"JC125",0);g.players[0].society_zone.card=Some(g.make_card("MSBQ02",0));let core=field(&mut g,"BQ046",0);g.core_zones.push(crate::core_zone::CoreZone{owner:0,definition:"BQ046".into(),rest:0,card:None});act(&mut g,0,play(&id,"mobility",None));top(&mut g);assert_eq!(g.players[0].honor,1);assert!(g.has_mobility(g.board(&token).unwrap().1));assert!(g.has_mobility(g.board(&core).unwrap().1));assert!(!g.has_mobility(g.board(&enemy).unwrap().1));assert!(!g.has_mobility(g.board(&ordinary).unwrap().1));let later=field(&mut g,"TK010",0);assert!(!g.has_mobility(g.board(&later).unwrap().1));restore(&mut g);g.hide_in_place(&token);assert!(!g.bq049_grants.iter().any(|p|p.recipient.id==token));restore(&mut g);}
#[test]fn bq049_restore_rejects_missing_mode_payment_and_grant_identity(){let(mut g,id)=setup();let token=field(&mut g,"TK010",0);act(&mut g,0,play(&id,"mobility",None));for n in 0..4{let mut x=g.clone();let i=x.stack.last_mut().unwrap();if n==0{i.frame=None;}else{let f=i.frame.as_mut().unwrap();match n{1=>f.source.card.definition="JC001".into(),2=>f.steps.clear(),_=>f.already_paid.clear()}}bad(&g,&x);}top(&mut g);for n in 0..4{let mut x=g.clone();let p=&mut x.bq049_grants[0];match n{0=>p.turn+=1,1=>p.recipient.definition="JC125".into(),2=>p.frame.steps[0].op=Op::BQ049Generate,_=>p.recipient.generated=None};bad(&g,&x);}let mut x=g.clone();x.bq049_grants.push(x.bq049_grants[0].clone());bad(&g,&x);assert!(g.board(&token).is_some());restore(&mut g);}

fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let room=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let cmd=serde_json::from_value(s["command"].clone()).unwrap();let d=room.transition(s["seat"].as_u64().unwrap()as usize,Some(cmd),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}v}

#[test]fn bq049_payment_payload_target_replacement_and_physical_sacrifice(){
 let(mut g,id)=setup();let mut a=play(&id,"mobility",None);a.target_id=Some("region:0".into());reject(&mut g,0,a);g.players[0].assets.clear();reject(&mut g,0,play(&id,"generate",Some("region:0")));fund(&mut g,0,"JC063",2);reject(&mut g,0,play(&id,"generate",Some("region:0")));
 let(mut g,id)=setup();act(&mut g,0,play(&id,"generate",Some("region:0")));g.regions[0].card=g.make_card("DQJC115",0);top(&mut g);assert!(!g.batch3_physical_cards().any(|c|c.definition=="TK010"));restore(&mut g);
 let(mut g,id)=setup();let v=field(&mut g,"JC125",0);act(&mut g,0,play(&id,"sacrifice",None));top(&mut g);choose(&mut g,vec![v]);assert!(g.players[0].graveyard.iter().any(|c|c.definition=="JC125"));assert_eq!(g.players[0].honor,4);
}
#[test]fn bq049_real_mobility_destination_response_and_expiry(){for leave in [false,true]{let(mut g,id)=setup();let token=field(&mut g,"TK010",0);act(&mut g,0,play(&id,"mobility",None));top(&mut g);g.begin_window(Window::Mobility);let(r,c)=g.board(&token).unwrap();let source=g.mobility_source(c,r);g.emit_event(0,source,Event::ConfrontationStart);g.drive().unwrap();restore(&mut g);let target=g.pending.as_ref().unwrap().choice.options[0].id.clone();let destination:usize=target.strip_prefix("region:").unwrap().parse().unwrap();choose(&mut g,vec![target]);if leave{g.hide_in_place(&token);}top(&mut g);if !leave{assert_eq!(g.board(&token).unwrap().0,destination);g.effect(Effect::NextTurn).unwrap();assert!(g.bq049_grants.is_empty());}restore(&mut g);}}
fn prepared(mode:&str,index:usize)->serde_json::Value{use crate::abi112_review_play_tests::Trace;let(mut g,id)=setup();if mode!="generate"{field(&mut g,"TK010",0);}let mut t=Trace::new_preserving_rng(g,format!("bq049-prepared-{mode}"),index);t.action(0,play(&id,mode,if mode=="generate"{Some("region:0")}else{None}));for _ in 0..50{if let Some(p)=t.room.game.pending.clone(){t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}else if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}else{t.pass();}}assert!(t.room.game.pending.is_none());duplicate(t.value())}
fn constructed(seed:u64)->(Game,crate::deck::DeckDraft){let mut d=crate::deck::preset("watchers").unwrap();d.id="closed-bq049-natural".into();d.name="吞噬蔓延私有输入".into();d.society_id=None;d.core_card_id=None;d.cards=[(b::ID,3),("JC042",3),("JC125",44)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(crate::deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();for c in &mut cards{if [b::ID].contains(&c.id.as_str()){c.supported=true;}}let d=crate::deck::validate_with_registry(d,&cards,&catalog::catalog().societies).unwrap();let mut other=crate::deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=crate::deck::validate(other).unwrap();let mut g=Game::new("bq049-natural".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d.clone(),other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();(g,d)}

fn natural()->serde_json::Value{use crate::abi112_review_play_tests::Trace;let(seed,g,d)=(1..2049).find_map(|seed|{let(g,d)=constructed(seed);let h=&g.players[0].hand;(h.iter().any(|c|c.definition==b::ID)&&h.iter().any(|c|c.definition=="JC042")).then_some((seed,g,d))}).expect("bounded dealt red command hand");let mut t=Trace::new_preserving_rng(g,"bq049-natural-paid-generation".into(),730);let mut played=false;for _ in 0..1500{if let Some(p)=t.room.game.pending.clone(){t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());continue;}if played&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}let g=&t.room.game;let legal=g.legal_actions(0);let a=if g.players[0].assets.len()<2{let red=g.players[0].assets.iter().any(|c|c.definition=="JC042");legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&if red{c.definition=="JC125"}else{c.definition=="JC042"})))}else if !played{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(b::KEY)&&a.action.option.as_deref()==Some("generate"))}else{None};if let Some(a)=a{if a.action.ability_id.as_deref()==Some(b::KEY){played=true;}t.action(0,a.action.clone());}else{t.pass();}}
 assert!(played);assert_eq!(t.room.game.regions.iter().flat_map(|r|&r.cards).filter(|c|c.definition=="TK010"&&c.owner==0&&c.generated.is_some()).count(),1);let mut v=t.value();v["construction"]=serde_json::json!({"deck":d,"seed":seed,"privateRegistryOnly":true,"privateRegistryCandidates":[b::ID],"noLayoutOrResourceMutation":true});duplicate(v)}

fn generation_cycle()->serde_json::Value{use crate::abi112_review_play_tests::Trace;let(mut g,first)=setup();fund(&mut g,0,"JC042",4);let second=held(&mut g,b::ID,0);let third=held(&mut g,b::ID,0);let mut t=Trace::new_preserving_rng(g,"bq049-prepared-real-generation-grant-sacrifice".into(),734);for(id,mode)in[(first,"generate"),(second,"mobility"),(third,"sacrifice")]{t.action(0,play(&id,mode,if mode=="generate"{Some("region:0")}else{None}));for _ in 0..40{if let Some(p)=t.room.game.pending.clone(){t.choose(p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());}else if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}else{t.pass();}}if mode=="generate"{assert_eq!(t.room.game.regions[0].cards.iter().filter(|c|c.generated.is_some()).count(),1);}if mode=="mobility"{assert!(t.room.game.has_mobility(&t.room.game.regions[0].cards[0]));}}
assert_eq!(t.room.game.players[0].honor,5);assert!(!t.room.game.batch3_physical_cards().any(|c|c.definition=="TK010"));assert!(t.room.game.bq049_grants.is_empty());duplicate(t.value())}
#[test]fn bq049_native_natural_and_three_modes_room_export(){let cases=vec![natural(),prepared("generate",731),prepared("mobility",732),prepared("sacrifice",733),generation_cycle()];let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/bq049.rs",include_bytes!("bq049.rs").as_slice()),("rust-game/src/bq049_tests.rs",include_bytes!("bq049_tests.rs").as_slice())]{binding["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}if let Ok(p)=std::env::var("BQ049_NATIVE_OUT"){std::fs::write(p,serde_json::to_vec(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}

#[test]fn bq049_restart_and_elimination_clear_departed_grants(){
 let(mut g,id)=setup();field(&mut g,"TK010",0);let other=field(&mut g,"TK010",1);g.board_mut(&other).unwrap().controller=0;act(&mut g,0,play(&id,"mobility",None));top(&mut g);assert_eq!(g.bq049_grants.len(),2);let mut restarted=g.clone();restarted.finish(0);restarted.start().unwrap();assert!(restarted.bq049_grants.is_empty());restore(&mut restarted);g.eliminate(0);assert_eq!(g.bq049_grants.len(),1);assert_eq!(g.bq049_grants[0].recipient.owner,1);restore(&mut g);
}
